function dateLabel(date: string) { return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric' }).format(new Date(date)) }
function initials(name: string) { return name.split(' ').map((part) => part[0]).join('').slice(0, 2) }
function safeReferenceUrl(value: string) { try { const url = new URL(value); return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : undefined } catch { return undefined } }
function normalizeSearchText(value: string) { return value.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim() }
function matchesSearch(query: string, ...fields: string[]) { const terms = normalizeSearchText(query).split(/\s+/).filter(Boolean); const text = normalizeSearchText(fields.join(' ')); return terms.every((term) => text.includes(term)) }

function useSavedArticles() {
  const { data: user } = useSWR(appConfig.dataMode === 'api' ? 'deci-current-user' : null, currentUserFetcher)
  const key = appConfig.dataMode === 'demo' ? 'demo-saved-articles' : user ? ['saved-articles', user.id] : null
  const { data: slugs = [], mutate } = useSWR<string[]>(key, () => appConfig.dataMode === 'demo' ? demoRepositories.bookmarks.list().map((bookmark) => bookmark.articleSlug) : getSavedArticleSlugs())
  const toggle = (slug: string) => {
    if (appConfig.dataMode === 'api' && !user) {
      window.location.assign(`/auth/login?next=${encodeURIComponent(window.location.pathname)}`)
      return
    }
    const wasSaved = slugs.includes(slug)
    if (appConfig.dataMode === 'demo') {
      demoRepositories.bookmarks.toggle(slug)
      void mutate(demoRepositories.bookmarks.list().map((bookmark) => bookmark.articleSlug), { revalidate: false })
      return
    }
    void mutate(async (current = []) => {
      await toggleSavedArticle(slug, wasSaved)
      return wasSaved ? current.filter((item) => item !== slug) : [...current, slug]
    }, { optimisticData: wasSaved ? slugs.filter((item) => item !== slug) : [...slugs, slug], rollbackOnError: true, revalidate: false })
      .catch(() => window.alert('Your reading list could not be updated. Please try again.'))
  }
  return { slugs, toggle }
}

function Avatar({ name, color = 'sage', size = 'sm' }: { name: string; color?: string; size?: 'sm' | 'lg' }) {
  return <span aria-label={name} className={`avatar avatar-${color} ${size === 'lg' ? 'avatar-lg' : ''}`}>{initials(name)}</span>
}

function ArticleCard({ article, featured = false }: { article: Article; featured?: boolean }) {
  const { slugs, toggle } = useSavedArticles()
  const saved = slugs.includes(article.slug)
  return <article className={`article-card ${featured ? 'article-featured' : ''}`}>
    <div className="article-card-top"><Link className="topic-label" href={`/topics/${article.topic.toLowerCase().replaceAll(' ', '-')}`}>{article.topic}</Link><button className={`icon-button save-button ${saved ? 'is-saved' : ''}`} aria-label={saved ? 'Remove saved article' : 'Save article'} aria-pressed={saved} onClick={() => toggle(article.slug)}><Bookmark size={16} fill={saved ? 'currentColor' : 'none'} /></button></div>
    <h3><Link href={`/articles/${article.slug}`}>{article.title}</Link></h3><p className="article-summary">{article.summary}</p>
    <div className="article-card-bottom"><div className="author-mini"><Avatar name={article.author} /><span>{article.author}</span><span className="meta-dot">·</span><span>{dateLabel(article.updatedAt)}</span></div><span className="read-time">{article.readingTime} min</span></div>
  </article>
}

function SearchBox({ initial = '' }: { initial?: string }) {
  const router = useRouter(); const [query, setQuery] = useState(initial)
  return <form className="search-box" onSubmit={(event) => { event.preventDefault(); router.push(`/search?q=${encodeURIComponent(query)}`) }}><Search size={18} /><input aria-label="Search Decipedia" placeholder="Search the commons..." value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && (event.nativeEvent.isComposing || event.keyCode === 229)) event.preventDefault() }} /><kbd>⌘ K</kbd><button aria-label="Search" type="submit"><ArrowRight size={16} /></button></form>
}

