function Topbar({ onMenu, onTheme, dark }: { onMenu: () => void; onTheme: () => void; dark: boolean }) {
  const [walletOpen, setWalletOpen] = useState(false); const [searchOpen, setSearchOpen] = useState(false); const router = useRouter()
  useEffect(() => { const listener = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setSearchOpen(true) } if (event.key === 'Escape') setSearchOpen(false) }; window.addEventListener('keydown', listener); return () => window.removeEventListener('keydown', listener) }, [])
  return <><header className="topbar"><button className="icon-button mobile-menu" aria-label="Open menu" onClick={onMenu}><Menu size={20} /></button><div className="top-search-trigger" onClick={() => setSearchOpen(true)} role="button" tabIndex={0} onKeyDown={(event) => event.key === 'Enter' && setSearchOpen(true)}><Search size={16} /><span>Search articles, topics, contributors...</span><kbd>⌘ K</kbd></div><div className="topbar-actions"><button aria-label="Toggle color theme" className="icon-button theme-toggle" onClick={onTheme}>{dark ? <Sun size={18} /> : <Moon size={18} />}</button><Link aria-label="Notifications" className="icon-button notification-trigger" href="/notifications"><span className="notification-dot" /><Activity size={18} /></Link><span className="top-divider" /><AccountActions /><button className="wallet-button" onClick={() => setWalletOpen(true)}><Wallet size={15} /><span>Connect wallet</span></button></div></header>
    {searchOpen && <div className="search-overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) setSearchOpen(false) }}><div className="search-modal"><div className="search-modal-input"><Search size={19} /><input autoFocus aria-label="Search knowledge, topics, and people" placeholder="Search knowledge, topics, people..." onKeyDown={(event) => { if (event.key === 'Enter' && (event.nativeEvent.isComposing || event.keyCode === 229)) return; if (event.key === 'Enter') { router.push(`/search?q=${encodeURIComponent(event.currentTarget.value)}`); setSearchOpen(false) } }} /><button className="icon-button" onClick={() => setSearchOpen(false)} aria-label="Close search"><X size={18} /></button></div><div className="search-suggestions"><span className="eyebrow">POPULAR RIGHT NOW</span>{articles.slice(0, 3).map((article) => <Link key={article.slug} href={`/articles/${article.slug}`} onClick={() => setSearchOpen(false)}><BookOpen size={16} /><span>{article.title}</span><ArrowUpRight size={14} /></Link>)}</div><div className="search-hint">Press <kbd>ESC</kbd> to close <span>Search across the knowledge commons</span></div></div></div>}
    {walletOpen && <div className="search-overlay" onMouseDown={(event) => { if (event.target === event.currentTarget) setWalletOpen(false) }}><div className="wallet-modal"><button className="modal-close icon-button" onClick={() => setWalletOpen(false)} aria-label="Close"><X size={18} /></button><span className="wallet-modal-icon"><Wallet size={22} /></span><span className="eyebrow">{appConfig.network.toUpperCase()}</span><h2>Wallet support is pending</h2><p>Decipedia does not yet have a verified GnoConnect provider or article realm contract, so no transaction can be signed or broadcast.</p><div className="wallet-unavailable"><span className="status-dot muted-dot" />Network: {appConfig.networkConfigured ? appConfig.network : 'Not configured'}</div><div className="wallet-unavailable"><span className="status-dot muted-dot" />Article realm: {appConfig.articleRealm || 'Not configured'}</div><button className="button button-dark full-width" onClick={() => setWalletOpen(false)}>Got it</button><p className="privacy-note"><LockKeyhole size={12} /> Decipedia will never ask for your recovery phrase.</p></div></div>}
  </>
}

