function ArticleRow({ article }: { article: Article }) { return <Link className="article-row" href={`/articles/${article.slug}`}><span className="row-icon"><BookOpen size={17} /></span><span className="row-main"><b>{article.title}</b><span>{article.summary}</span></span><span className="row-topic">{article.topic}</span><span className="row-date">{dateLabel(article.updatedAt)}</span><ArrowUpRight className="row-arrow" size={15} /></Link> }

export function ExploreView() {
  const params = useSearchParams(); const router = useRouter(); const [filter, setFilter] = useState(params.get('topic') || 'All topics'); const [query, setQuery] = useState(params.get('q') || ''); const [sort, setSort] = useState('updated')
  const filtered = useMemo(() => articles.filter((article) => (filter === 'All topics' || article.topic === filter) && matchesSearch(query, article.title, article.summary, article.tags.join(' '))).sort((a, b) => sort === 'reading' ? a.readingTime - b.readingTime : sort === 'revisions' ? b.revisions - a.revisions : new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()), [filter, query, sort])
  const matchingTopics = topics.filter((topic) => matchesSearch(query, topic.name, topic.description))
  const matchingContributors = contributors.filter((person) => matchesSearch(query, person.name, person.username, person.bio))
  const update = (nextFilter: string) => { setFilter(nextFilter); const next = new URLSearchParams(); if (nextFilter !== 'All topics') next.set('topic', nextFilter); if (query) next.set('q', query); router.replace(`/explore${next.size ? `?${next}` : ''}`) }
  return <PageIntro eyebrow="THE KNOWLEDGE COMMONS" title="Explore" description="Find a new idea, follow a thread, or dive deep into something you love."><div className="explore-controls"><div className="explore-search"><Search size={17} /><input placeholder="Search articles..." value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="select-wrap"><Filter size={15} /><select aria-label="Filter by topic" value={filter} onChange={(event) => update(event.target.value)}><option>All topics</option>{topics.map((topic) => <option key={topic.slug}>{topic.name}</option>)}</select><ChevronDown size={14} /></div><div className="select-wrap select-sort"><ListFilter size={15}/><select aria-label="Sort articles" value={sort} onChange={(event) => setSort(event.target.value)}><option value="updated">Recently updated</option><option value="reading">Shortest read</option><option value="revisions">Most revised</option></select><ChevronDown size={14}/></div></div>{query && <div className="search-category-results"><div><span className="eyebrow">TOPICS</span>{matchingTopics.length ? matchingTopics.map((topic) => <Link key={topic.slug} href={`/topics/${topic.slug}`}>{topic.name}</Link>) : <span>No matching topics</span>}</div><div><span className="eyebrow">CONTRIBUTORS</span>{matchingContributors.length ? matchingContributors.map((person) => <Link key={person.username} href={`/contributors/${person.username}`}>{person.name}</Link>) : <span>No matching contributors</span>}</div></div>}<div className="results-label">{filtered.length} articles <span>·</span> Sorted by {sort === 'updated' ? 'recently updated' : sort === 'reading' ? 'shortest read' : 'most revised'}</div><div className="explore-list">{filtered.length ? filtered.map((article) => <ArticleRow article={article} key={article.slug} />) : <div className="empty-state"><Search size={24} /><h3>No articles found</h3><p>Try a different search or clear your filters.</p><button className="button button-outline" onClick={() => { setFilter('All topics'); setQuery(''); setSort('updated'); router.replace('/explore') }}>Clear filters</button></div>}</div></PageIntro>
}

function PageIntro({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: React.ReactNode }) { return <div className="page-intro"><div className="page-heading"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{children}</div> }

export function TopicsView({ selected }: { selected?: string }) { const selectedTopic = topics.find((topic) => topic.slug === selected); const list = selectedTopic ? articles.filter((article) => article.topic === selectedTopic.name) : articles
  return <PageIntro eyebrow="FOLLOW YOUR CURIOSITY" title={selectedTopic?.name || 'Topics'} description={selectedTopic?.description || 'A map of the ideas, disciplines, and questions that make up our shared knowledge.'}><div className="topic-grid topic-directory">{(selectedTopic ? [selectedTopic] : topics).map((topic, index) => <Link href={`/topics/${topic.slug}`} className="topic-tile topic-tile-large" key={topic.slug}><span className={`topic-icon topic-icon-${index % 4}`}>{topic.icon}</span><span className="topic-title">{topic.name}</span><span className="topic-count">{topic.articleCount} articles</span><span className="topic-description">{topic.description}</span><ArrowUpRight size={14} className="topic-arrow" /></Link>)}</div><div className="section-heading inner-heading"><div><span className="eyebrow">FRESH THINKING</span><h2>{selectedTopic ? `In ${selectedTopic.name}` : 'Popular articles'}</h2></div><Link className="text-link" href="/explore">Explore all<ArrowRight size={15} /></Link></div><div className="recent-list">{list.map((article) => <ArticleRow article={article} key={article.slug} />)}</div></PageIntro>
}

export function ArticleView({ slug }: { slug: string }) {
  const article = articles.find((item) => item.slug === slug)
  const { slugs, toggle } = useSavedArticles()
  const saved = slugs.includes(slug)
  if (!article) return <PageIntro eyebrow="NOT FOUND" title="Article not found" description="This article may have been moved or removed."><Link className="button button-outline" href="/explore">Explore articles<ArrowRight size={15}/></Link></PageIntro>
  const headings = article.content.split('\n\n').map((paragraph) => paragraph.match(/^##\s+(.+)/)?.[1]).filter((heading): heading is string => Boolean(heading))
  const headingId = (heading: string) => heading.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')
  return <div className="article-layout"><article className="article-reader"><div className="breadcrumbs"><Link href="/">Home</Link><span>/</span><Link href={`/topics/${article.topic.toLowerCase().replaceAll(' ', '-')}`}>{article.topic}</Link><span>/</span><span>Article</span></div><Link className="article-topic-pill" href={`/topics/${article.topic.toLowerCase().replaceAll(' ', '-')}`}>{article.topic}</Link><h1>{article.title}</h1><p className="article-deck">{article.summary}</p><div className="article-byline"><Avatar name={article.author}/><div><b>{article.author}</b><span>Contributor · Updated {dateLabel(article.updatedAt)}</span></div><span className="byline-divider"/><span className="read-time"><Clock3 size={14}/>{article.readingTime} min read</span></div><div className="article-toolbar"><div><Link href={`/articles/${article.slug}/edit`}><Pencil size={15}/>Edit</Link><Link href={`/articles/${article.slug}/history`}><History size={15}/>History <span className="revision-count">{article.revisions}</span></Link><button aria-pressed={saved} onClick={() => toggle(article.slug)}><Bookmark size={15} fill={saved ? 'currentColor' : 'none'}/>{saved ? 'Saved' : 'Save'}</button></div><div><button onClick={() => navigator.clipboard?.writeText(window.location.href)}><Copy size={15}/>Share</button><button aria-label="More article actions"><MoreHorizontal size={17}/></button></div></div><div className="article-body"><ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeSanitize]} components={{ h2: ({ children }) => <h2 id={headingId(String(children))}>{children}</h2> }}>{article.content}</ReactMarkdown></div><div className="article-tags">{article.tags.map((tag) => <Link key={tag} href={`/search?q=${encodeURIComponent(tag)}`}><Tag size={12}/>{tag}</Link>)}</div>{article.references?.length ? <section className="article-references" aria-labelledby="article-references-title"><h2 id="article-references-title">References</h2><ol>{article.references.map((reference) => { const href = safeReferenceUrl(reference); return <li key={reference}>{href ? <a href={href} target="_blank" rel="noreferrer">{reference}</a> : <span>{reference}</span>}</li> })}</ol></section> : null}<div className="article-source-note"><span className="source-icon"><FileClock size={17}/></span><span><b>This article has an open history</b><small>{article.revisions} revisions · Changes are transparently attributed to contributors</small></span><Link href={`/articles/${article.slug}/history`}>View history<ArrowRight size={14}/></Link></div><section className="related-block"><div className="section-heading"><div><span className="eyebrow">KEEP EXPLORING</span><h2>Related articles</h2></div></div><div className="related-grid">{articles.filter((item) => item.slug !== article.slug).slice(0, 2).map((item) => <ArticleCard key={item.slug} article={item}/>)}</div></section></article><aside className="article-aside"><span className="eyebrow">ON THIS PAGE</span>{headings.map((heading) => <a key={heading} href={`#${headingId(heading)}`}>{heading}</a>)}<div className="aside-rule"/><span className="eyebrow">ARTICLE DETAILS</span><div className="aside-detail"><span>Last updated</span><b>{dateLabel(article.updatedAt)}, 2026</b></div><div className="aside-detail"><span>Reading time</span><b>{article.readingTime} minutes</b></div><div className="aside-detail"><span>Revision</span><b>#{article.revisions}</b></div><div className="aside-verification"><ShieldCheck size={15}/><span><b>History available</b><small>On-chain verification appears only when confirmed.</small></span></div></aside></div>
}

export function HistoryView({ slug, compare = false }: { slug: string; compare?: boolean }) { const searchParams = useSearchParams(); const router = useRouter(); const article = articles.find((item) => item.slug === slug); const revisionData = demoRepositories.revisions.list(slug); const revisions = revisionData.map((revision) => ({ n: revision.number, name: revision.author, date: revision.createdAt, message: revision.summary, id: revision.id, content: revision.snapshot ? `# ${revision.snapshot.title}\n\n${revision.snapshot.summary}\n\n${revision.snapshot.content}` : revision.content })); const fromId = searchParams.get('from') || revisions[1]?.id || revisions[0]?.id; const toId = searchParams.get('to') || revisions[0]?.id; const comparison = fromId && toId ? demoRepositories.revisions.compare(slug, fromId, toId) : undefined; const fromRevision = revisions.find((revision) => revision.id === fromId); const toRevision = revisions.find((revision) => revision.id === toId); const diff = comparison ? diffLines(comparison.before, comparison.after) : []; const updateSelection = (key: 'from' | 'to', value: string) => { const params = new URLSearchParams(searchParams.toString()); params.set(key, value); router.push(`/articles/${slug}/history/compare?${params.toString()}`) }; if (!article) return <PageIntro eyebrow="NOT FOUND" title="Article not found" description="This article may have been moved or removed."><Link className="button button-outline" href="/explore">Explore articles<ArrowRight size={15}/></Link></PageIntro>; return <PageIntro eyebrow="ARTICLE HISTORY" title={compare ? 'Compare revisions' : 'Revision history'} description={article.title}><div className="history-header"><span className="demo-note">Demo revision history · local edits are saved</span><Link className="back-link" href={`/articles/${slug}`}><ArrowLeft size={15}/>Back to article</Link><Link className="button button-outline" href={compare ? `/articles/${slug}/history` : `/articles/${slug}/history/compare`}>{compare ? 'All revisions' : 'Compare revisions'}<ArrowRight size={14}/></Link></div>{compare ? <div className="diff-panel"><div className="diff-heading"><span>Revision #{fromRevision?.n ?? '—'}</span><ArrowRight size={15}/><span>Revision #{toRevision?.n ?? '—'}</span></div><div className="revision-selectors"><label>From<select aria-label="Compare from revision" value={fromId || ''} onChange={(event) => updateSelection('from', event.target.value)}>{revisions.map((revision) => <option key={revision.id} value={revision.id}>Revision {revision.n} · {revision.name}</option>)}</select></label><label>To<select aria-label="Compare to revision" value={toId || ''} onChange={(event) => updateSelection('to', event.target.value)}>{revisions.map((revision) => <option key={revision.id} value={revision.id}>Revision {revision.n} · {revision.name}</option>)}</select></label></div>{comparison ? <div className="line-diff" aria-label="Line-by-line revision comparison">{diff.map((line, index) => <div className={`diff-line ${line.kind === 'added' ? 'diff-added' : line.kind === 'removed' ? 'diff-removed' : 'diff-same'}`} key={`${index}-${line.kind}`}><span aria-hidden="true">{line.kind === 'added' ? '+' : line.kind === 'removed' ? '−' : ' '}</span><code>{line.value || ' '}</code></div>)}</div> : <p className="diff-note">This demo includes only one stored snapshot for this article. Earlier content is unavailable, so no historical diff is shown.</p>}<p className="diff-note">Only stored snapshots are compared. No blockchain proof is implied.</p></div> : <div className="revision-list">{revisions.map((revision, index) => <div className="revision-item" key={revision.n}><div className="timeline-rail">{index === 0 ? <span className="timeline-current"><Check size={12}/></span> : <span className="timeline-node"/>}{index !== revisions.length - 1 && <span className="timeline-line"/>}</div><Avatar name={revision.name}/><div className="revision-content"><div className="revision-title"><b>Revision {revision.n}</b>{index === 0 && <span className="current-tag">Current</span>}</div><p>{revision.message}</p><span className="revision-meta">{revision.name} · {dateLabel(revision.date)}, 2026</span></div><Link className="icon-button" aria-label={`Compare revision ${revision.n}`} href={`/articles/${slug}/history/compare?from=${revisions[index + 1]?.id || revision.id}&to=${revision.id}`}><ArrowUpRight size={15}/></Link></div>)}</div>}</PageIntro> }

export function ContributorsView({ username }: { username?: string }) { const person = contributors.find((item) => item.username === username); return <PageIntro eyebrow="THE PEOPLE BEHIND THE PAGES" title={person?.name || 'Contributors'} description={person?.bio || 'Meet the people building a more open and generous knowledge commons.'}><ContributorDirectory username={username}/></PageIntro> }

function draftRoute(draft: { id: string; article_slug?: string | null; articleSlug?: string | null }) {
  const articleSlug = draft.article_slug ?? draft.articleSlug
  return articleSlug ? `/articles/${articleSlug}/edit?draft=${draft.id}` : `/articles/new?draft=${draft.id}`
}

export function EditorView({ slug }: { slug?: string }) { const searchParams = useSearchParams(); const router = useRouter(); const requestedDraft = searchParams.get('draft'); const [draftKey, setDraftKey] = useState(() => requestedDraft || (slug ? crypto.randomUUID() : '')); const article = slug ? articles.find((item) => item.slug === slug) : undefined; const [title, setTitle] = useState(article?.title || ''); const [summary, setSummary] = useState(article?.summary || ''); const [topic, setTopic] = useState(article?.topic || ''); const [tagInput, setTagInput] = useState(article?.tags.join(', ') || ''); const [referenceInput, setReferenceInput] = useState(article?.references?.join('\n') || ''); const [content, setContent] = useState(article?.content || ''); const [contentHistory, setContentHistory] = useState<string[]>([]); const [redoHistory, setRedoHistory] = useState<string[]>([]); const [preview, setPreview] = useState(false); const [notice, setNotice] = useState(''); const [draftReady, setDraftReady] = useState(false); const [savingDraft, setSavingDraft] = useState(false); const [publishing, setPublishing] = useState(false); const [uploadingImage, setUploadingImage] = useState(false); const contentRef = useRef<HTMLTextAreaElement>(null); const imageInputRef = useRef<HTMLInputElement>(null); const editorArticleInitialized = useRef<string | null>(null); const { data: user } = useSWR(appConfig.dataMode === 'api' ? 'deci-current-user' : null, currentUserFetcher); const draftQueryKey = appConfig.dataMode === 'demo' ? 'demo-drafts' : user ? ['user-drafts', user.id] : null; const { data: draftRows, mutate: refreshDrafts } = useSWR(draftQueryKey, async () => appConfig.dataMode === 'demo' ? demoRepositories.drafts.list() : await listUserDrafts()); useEffect(() => { if (slug && !requestedDraft) { if (article && editorArticleInitialized.current !== article.slug) { editorArticleInitialized.current = article.slug; setTitle(article.title); setSummary(article.summary); setTopic(article.topic); setTagInput(article.tags.join(', ')); setReferenceInput((article.references || []).join('\n')); setContent(article.content) } if (draftKey) router.replace(`/articles/${slug}/edit?draft=${draftKey}`); setDraftReady(true); return } if (!draftKey) { const id = requestedDraft || crypto.randomUUID(); setDraftKey(id); if (!requestedDraft) router.replace(`/articles/new?draft=${id}`); return } if (appConfig.dataMode === 'demo') { const draft = demoRepositories.drafts.get(draftKey); if (draft) { setTitle(draft.title); setSummary(draft.summary); setTopic(draft.topic); setTagInput(draft.tags.join(', ')); setReferenceInput(('references' in draft ? draft.references || [] : []).join('\n')); setContent(draft.content) } setDraftReady(true); return } if (!user || !draftRows) { setDraftReady(true); return } const draft = draftRows.find((item) => item.id === draftKey); if (draft) { setTitle(draft.title); setSummary(draft.summary); setTopic(draft.topic); setTagInput(draft.tags.join(', ')); setReferenceInput(('references' in draft ? draft.references || [] : []).join('\n')); setContent(draft.content) } setDraftReady(true) }, [article?.slug, draftKey, draftRows, requestedDraft, slug, user]); const words = content.trim() ? content.trim().split(/\s+/).length : 0; useEffect(() => { if (!draftReady || !draftKey || (appConfig.dataMode === 'api' && !user) || !(title || summary || content || topic || tagInput || referenceInput)) return; const timeout = window.setTimeout(() => { const draftData = { id: draftKey, title, summary, topic, tags: tagInput.split(',').map((tag) => tag.trim()).filter(Boolean), references: referenceInput.split('\n').map((reference) => reference.trim()).filter(Boolean), content }; if (appConfig.dataMode === 'demo') { demoRepositories.drafts.save({ ...draftData, articleSlug: article?.slug ?? null, savedAt: new Date().toISOString() }); void refreshDrafts() } else { void saveUserDraft({ ...draftData, article_slug: article?.slug ?? null }).then(() => refreshDrafts()).catch(() => setNotice('Autosave failed. Use Save draft to retry.')) } }, 700); return () => window.clearTimeout(timeout) }, [article, content, draftKey, draftReady, referenceInput, refreshDrafts, summary, tagInput, title, topic, user]); const changeContent = (next: string) => { if (next === content) return; setContentHistory((history) => [...history, content].slice(-50)); setRedoHistory([]); setContent(next) }; const undoContent = () => { const previous = contentHistory.at(-1); if (previous === undefined) return; setContentHistory((history) => history.slice(0, -1)); setRedoHistory((history) => [...history, content]); setContent(previous) }; const redoContent = () => { const next = redoHistory.at(-1); if (next === undefined) return; setRedoHistory((history) => history.slice(0, -1)); setContentHistory((history) => [...history, content].slice(-50)); setContent(next) }; const insertMarkdown = (before: string, after = before) => { const editor = contentRef.current; const start = editor?.selectionStart ?? content.length; const end = editor?.selectionEnd ?? content.length; const selected = content.slice(start, end); changeContent(`${content.slice(0, start)}${before}${selected}${after}${content.slice(end)}`); requestAnimationFrame(() => { editor?.focus(); editor?.setSelectionRange(start + before.length, start + before.length + selected.length) }) }; const saveDraft = async () => { if (appConfig.dataMode === 'demo') { setSavingDraft(true); try { demoRepositories.drafts.save({ id: draftKey, title, summary, topic, tags: tagInput.split(',').map((tag) => tag.trim()).filter(Boolean), references: referenceInput.split('\n').map((reference) => reference.trim()).filter(Boolean), content, articleSlug: article?.slug ?? null, savedAt: new Date().toISOString() }); await refreshDrafts(); setNotice(article ? 'Unpublished edit saved on this device.' : 'Draft saved on this device.') } catch { setNotice('Your changes could not be saved. Please try again.') } finally { setSavingDraft(false) } return } if (!user) { window.location.assign(`/auth/login?next=${encodeURIComponent(window.location.pathname)}`); return } setSavingDraft(true); try { await saveUserDraft({ id: draftKey, title, summary, topic, tags: tagInput.split(',').map((tag) => tag.trim()).filter(Boolean), references: referenceInput.split('\n').map((reference) => reference.trim()).filter(Boolean), content, article_slug: article?.slug ?? null }); await refreshDrafts(); setNotice(article ? 'Unpublished edit saved to your account.' : 'Draft saved to your account.') } catch { setNotice('Draft could not be saved. Please try again.') } finally { setSavingDraft(false) } }; return <div className="editor-page"><div className="editor-top"><Link className="back-link" href={article ? `/articles/${article.slug}` : '/'}><ArrowLeft size={15}/>Exit editor</Link><span className="draft-state"><span/>{draftReady ? 'Ready to draft' : 'Loading your draft'}</span><div className="editor-actions"><button className="button button-quiet" onClick={() => void saveDraft()} disabled={savingDraft}>{savingDraft ? 'Saving…' : article || slug ? 'Save changes' : 'Save draft'}</button><button className="button button-dark" onClick={async () => { if (publishing) return; const invalidReferences = referenceInput.split('\n').map((reference) => reference.trim()).filter(Boolean).filter((reference) => !safeReferenceUrl(reference)); if (!title.trim() || title.trim().length > 160 || !summary.trim() || summary.trim().length > 320 || !topic || !content.trim()) { setNotice('Add a title (1–160 characters), summary (1–320 characters), topic, and article content before publishing.'); return } if (invalidReferences.length) { setNotice('Each reference must be a valid HTTP or HTTPS URL.'); return } if (appConfig.dataMode !== 'demo') { setNotice('Publishing requires the configured wallet provider and verified article realm. Your draft is safe.'); return } setPublishing(true); try { const input = { title: title.trim(), summary: summary.trim(), topic, tags: tagInput.split(',').map((tag) => tag.trim()).filter(Boolean), references: referenceInput.split('\n').map((reference) => reference.trim()).filter(Boolean), content: content.trim() }; const published = article ? await demoRepositories.articles.update?.(article.slug, input) : await demoRepositories.articles.create?.(input); if (!published) throw new Error('Could not save article'); if (!article) demoRepositories.drafts.remove(draftKey); router.push(`/articles/${published.slug}`) } catch { setNotice('Article could not be saved. Please try again.') } finally { setPublishing(false) } }} disabled={publishing}>{publishing ? 'Publishing…' : 'Publish'}<ArrowRight size={14}/></button></div></div><div className="editor-layout"><div className="editor-main"><span className="eyebrow">{article ? 'EDITING ARTICLE' : 'NEW ARTICLE'}</span><input className="editor-title" placeholder="Give your article a clear title" value={title} onChange={(event) => setTitle(event.target.value)}/><textarea className="editor-summary" aria-label="Article summary" placeholder="A short summary helps readers know what this is about..." value={summary} onChange={(event) => setSummary(event.target.value)}/><label className="editor-field reference-field"><span>References</span><textarea aria-label="References, one URL per line" rows={3} placeholder="Add source URLs, one per line" value={referenceInput} onChange={(event) => setReferenceInput(event.target.value)}/></label><div className="editor-tags"><label className="editor-field"><span>Topic</span><select aria-label="Article topic" value={topic} onChange={(event) => setTopic(event.target.value)}><option value="">Choose a topic</option>{topics.map((item) => <option value={item.name} key={item.slug}>{item.name}</option>)}</select></label><label className="editor-field"><span>Tags</span><input aria-label="Article tags, separated by commas" value={tagInput} onChange={(event) => setTagInput(event.target.value)} placeholder="Add tags, separated by commas"/></label></div><div className="editor-toolbar"><button type="button" aria-label="Bold selected text" onClick={() => insertMarkdown('**')}><b>B</b></button><button type="button" aria-label="Italic selected text" onClick={() => insertMarkdown('*')}><i>I</i></button><span/><button type="button" onClick={() => insertMarkdown('\n## ', '\n')}>H2</button><button type="button" onClick={() => insertMarkdown('\n- ', '')}>List</button><button type="button" aria-label="Format selected text as a link" onClick={() => insertMarkdown('[', '](https://)')}><ArrowUpRight size={14}/></button><button type="button" aria-label="Undo" onClick={undoContent} disabled={!contentHistory.length}>Undo</button><button type="button" aria-label="Redo" onClick={redoContent} disabled={!redoHistory.length}>Redo</button><button type="button" aria-label="Insert code block" onClick={() => insertMarkdown('\n```\n', '\n```\n')}>Code</button><button type="button" aria-label="Insert Markdown table" onClick={() => insertMarkdown('\n| Column | Column |\n| --- | --- |\n| Value | Value |\n')}>Table</button><input ref={imageInputRef} type="file" accept="image/png,image/jpeg,image/webp,image/gif" className="sr-only" aria-label="Choose image to upload" onChange={async (event) => { const file = event.currentTarget.files?.[0]; event.currentTarget.value = ''; if (!file) return; if (file.size > 5 * 1024 * 1024) { setNotice('Choose an image smaller than 5 MB.'); return } setUploadingImage(true); try { const formData = new FormData(); formData.append('file', file); const response = await fetch('/api/article-images', { method: 'POST', body: formData }); const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Upload failed'); insertMarkdown(`![${file.name.replace(/[\\[\\]\\n]/g, '').slice(0, 120)}](${result.url})`, ''); setNotice('Image uploaded and inserted into your article.'); } catch (error) { setNotice(error instanceof Error ? error.message : 'Image upload failed. Please try again.') } finally { setUploadingImage(false) } }} /><button type="button" aria-label="Upload image" onClick={() => imageInputRef.current?.click()} disabled={uploadingImage}><Upload size={14}/>{uploadingImage ? 'Uploading…' : 'Image'}</button><button onClick={() => setPreview(!preview)}>{preview ? 'Edit' : 'Preview'}</button></div>{preview ? <div className="editor-preview"><h2>{title || 'Your article title'}</h2><p>{summary || 'Your article summary will appear here.'}</p><div className="article-body"><ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeSanitize]}>{content || 'Your article preview will appear here.'}</ReactMarkdown></div></div> : <textarea ref={contentRef} className="markdown-input" aria-label="Article content in Markdown" placeholder={'Start with an introduction...\n\n## Your first section\n\nShare what you know. Cite your sources, explain your reasoning, and help others learn.'} value={content} onChange={(event) => changeContent(event.target.value)}/>}<div className="editor-footer"><span>{words} words</span><span>About {Math.max(1, Math.ceil(words / 220))} min read</span></div>{notice && <div className="editor-notice"><CircleHelp size={16}/>{notice}<button onClick={() => setNotice('')} aria-label="Dismiss"><X size={14}/></button></div>}</div><aside className="editor-sidebar"><span className="eyebrow">PUBLISHING CHECKLIST</span><h3>Ready to share?</h3><p>A few thoughtful details help your work find its readers.</p><div className="checklist-item"><Check size={14}/>Clear, descriptive title</div><div className="checklist-item"><Check size={14}/>Helpful article summary</div><div className="checklist-item"><span className="check-empty"/>Choose a topic</div><div className="checklist-item"><span className="check-empty"/>Add references</div><div className="editor-guidance"><BookOpen size={15}/><b>Write for understanding</b><span>Use clear language, cite reliable sources, and welcome new readers.</span></div><div className="editor-guidance"><Globe2 size={15}/><b>Publishing to the network</b><span>Publishing is unavailable until a wallet and article realm are configured.</span></div></aside></div></div> }

export function DashboardView() { return appConfig.dataMode === 'demo' ? <DemoDashboard /> : <PageIntro eyebrow="YOUR SPACE IN THE COMMONS" title="Welcome, reader" description="Your contributions, saved knowledge, and community updates live here."><div className="guest-banner"><span className="guest-icon"><Wallet size={20}/></span><span><b>Connect a wallet to make your mark</b><small>Identity is required to publish articles and track your contributions.</small></span><span className="demo-note">Demo environment</span></div><div className="dashboard-grid"><div className="dashboard-card"><span className="eyebrow">YOUR CONTRIBUTIONS</span><h3>A growing story</h3><p>Connect a wallet to see your articles and revisions here.</p><Link href="/articles/new" className="text-link">Write an article<ArrowRight size={14}/></Link></div><div className="dashboard-card"><span className="eyebrow">SAVED KNOWLEDGE</span><h3>Keep good ideas close</h3><p>Save articles to return to them whenever you need.</p><Link href="/saved" className="text-link">View saved articles<ArrowRight size={14}/></Link></div><div className="dashboard-card"><span className="eyebrow">YOUR NEXT STEP</span><h3>Find something fascinating</h3><p>Explore the commons and follow questions that matter to you.</p><Link href="/explore" className="text-link">Explore articles<ArrowRight size={14}/></Link></div></div></PageIntro> }

export function SimpleView({ path }: { path: string }) { const router = useRouter(); const [message, setMessage] = useState(''); const { data: user } = useSWR(appConfig.dataMode === 'api' ? 'deci-current-user' : null, currentUserFetcher); const draftsKey = appConfig.dataMode === 'demo' ? 'demo-drafts' : user ? ['user-drafts', user.id] : null; const { data: drafts = [], mutate: refreshDrafts } = useSWR(draftsKey, async () => appConfig.dataMode === 'demo' ? demoRepositories.drafts.list() : await listUserDrafts()); const { slugs, toggle } = useSavedArticles(); const savedArticles = articles.filter((article) => slugs.includes(article.slug)); const titles: Record<string, [string, string, string]> = { '/activity': ['COMMUNITY PULSE', 'Activity', 'A transparent view of what the community is creating and improving.'], '/saved': ['YOUR READING LIST', 'Saved articles', 'Keep the knowledge you want to come back to close at hand.'], '/contributions': ['YOUR WORK', 'My contributions', 'Your articles, revisions, and drafts in one place.'], '/notifications': ['STAY IN THE LOOP', 'Notifications', 'Updates about articles and activity you follow.'], '/settings': ['MAKE IT YOURS', 'Settings', 'Manage your profile, preferences, and wallet connection.'], '/settings/profile': ['YOUR IDENTITY', 'Profile settings', 'Set up how you appear to the Decipedia community.'], '/settings/preferences': ['YOUR EXPERIENCE', 'Preferences', 'Choose how you want to read and explore.'], '/settings/wallet': ['NETWORK CONNECTION', 'Wallet settings', 'Manage your wallet and network preferences.'], '/settings/notifications': ['YOUR INBOX', 'Notification settings', 'Choose which updates matter to you.'], '/about': ['A SHARED RESOURCE', 'About Decipedia', 'Knowledge grows when everyone can contribute.'] }; const page = titles[path] || ['THE KNOWLEDGE COMMONS', 'Decipedia', 'Discover ideas shared by everyone.']; return <PageIntro eyebrow={page[0]} title={page[1]} description={page[2]}>{path === '/activity' ? <DemoActivityFeed /> : path === '/saved' ? <div className="recent-list">{savedArticles.length ? savedArticles.map((article) => <div className="activity-row" key={article.slug}><ArticleRow article={article}/><button className="button button-quiet" onClick={() => toggle(article.slug)}>Remove</button></div>) : <div className="empty-state"><Bookmark size={24}/><h3>No saved articles yet</h3><p>Use the bookmark action on an article to keep it here.</p><Link className="button button-outline" href="/explore">Explore articles</Link></div>}</div> : path.includes('/settings') ? <div className="settings-layout"><nav className="settings-nav">{[['Profile','/settings/profile'],['Preferences','/settings/preferences'],['Wallet','/settings/wallet'],['Notifications','/settings/notifications']].map(([label, href]) => <Link className={path === href || path === '/settings' && href === '/settings/profile' ? 'settings-active' : ''} href={href} key={href}>{label}</Link>)}</nav><div className="settings-panel"><h2>{page[1]}</h2><p>{path.includes('wallet') ? 'Your wallet is not connected. Connect a compatible GnoConnect wallet to publish and manage contributions.' : path.includes('preferences') ? 'Your reading preferences are saved to your account when signed in.' : path.includes('notifications') ? 'Notification settings sync when authenticated.' : 'Choose the name and short bio shown on your profile.'}</p>{path.includes('profile') && <ProfileSettings/>}{path.includes('preferences') && <div className="setting-row"><span><b>Appearance</b><small>Choose light or dark mode</small></span><button className="button button-outline" onClick={() => { const nextTheme = document.documentElement.classList.contains('dark') ? 'light' : 'dark'; document.documentElement.classList.toggle('dark', nextTheme === 'dark'); window.dispatchEvent(new Event('deci-theme-change')); if (appConfig.dataMode === 'demo') { demoRepositories.preferences.setTheme(nextTheme); setMessage('Appearance preference saved on this device.'); return } if (!user) { window.location.assign(`/auth/login?next=${encodeURIComponent(path)}`); return } void saveUserTheme(nextTheme).then(() => setMessage('Appearance preference saved to your account.')).catch(() => setMessage('Appearance preference could not be saved.')) }}>Toggle theme</button></div>}{path.includes('wallet') && <button className="button button-dark" onClick={() => setMessage('Wallet support is not enabled. Configure the Gno RPC, chain ID, article realm, and verified wallet provider first.')}><Wallet size={15}/>Wallet setup required</button>}{message && <p className="settings-feedback">{message}</p>}</div></div> : path === '/contributions' && appConfig.dataMode === 'demo' ? <DemoContributions /> : path === '/contributions' ? <div className="dashboard-grid"><section className="dashboard-card"><span className="eyebrow">PUBLISHED CONTRIBUTIONS</span><h3>Wallet-backed history</h3><p>Published contributions appear after an authenticated user and article backend are connected. No sample activity is presented as yours.</p><Link href="/articles/new" className="text-link">Start an article<ArrowRight size={14}/></Link></section><section className="dashboard-card"><span className="eyebrow">SAVED DRAFTS</span><h3>{drafts.length ? `${drafts.length} saved draft${drafts.length === 1 ? '' : 's'}` : 'No drafts yet'}</h3>{drafts.length ? <div className="recent-list">{drafts.map((draft) => <div className="activity-row" key={draft.id}><Link href={draftRoute(draft)} className="row-main"><b>{draft.title || 'Untitled draft'}</b><span>{draft.summary || 'Continue writing your article.'}</span></Link><button className="button button-quiet" onClick={() => { if (appConfig.dataMode === 'demo') { demoRepositories.drafts.remove(draft.id); void refreshDrafts(); return } void removeUserDraft(draft.id).then(() => refreshDrafts()).catch(() => setMessage('Draft could not be removed. Please try again.')) }}>Remove</button></div>)}</div> : <p>Drafts you save to your account will appear here.</p>}<Link href="/articles/new" className="text-link" onClick={(event) => { event.preventDefault(); router.push(`/articles/new?draft=${crypto.randomUUID()}`) }}>Create a draft<ArrowRight size={14}/></Link></section></div> : path === '/notifications' ? <DemoNotificationsFeed /> : path === '/about' ? <div className="about-content"><p>Decipedia is an open knowledge commons. We believe useful knowledge should be discoverable, collaborative, and accountable to the people who create it.</p><p>Contributions have transparent, attributable histories. Blockchain verification appears only when confirmed; the demo content here is illustrative, not on-chain data.</p><Link className="button button-dark" href="/explore">Explore the commons<ArrowRight size={15}/></Link></div> : <DashboardView/>}</PageIntro> }

export function DecipediaApp({ children }: { children: React.ReactNode }) {
  const pathname = usePathname(); const [mobileOpen, setMobileOpen] = useState(false); const [dark, setDark] = useState(false); const [demoStorageReady, setDemoStorageReady] = useState(appConfig.dataMode !== 'demo'); const { mutate: mutateCache } = useSWRConfig()
  const { data: user } = useSWR(appConfig.dataMode === 'api' ? 'deci-current-user' : null, currentUserFetcher)
  const { data: savedTheme } = useSWR(appConfig.dataMode === 'demo' ? 'demo-theme' : user ? ['user-theme', user.id] : null, () => appConfig.dataMode === 'demo' ? demoRepositories.preferences.getTheme() : getUserTheme())
  useEffect(() => { if (!demoStorageReady) { activateDemoStorage(); setDemoStorageReady(true); void mutateCache((key) => typeof key === 'string' && (key.startsWith('demo-') || key.startsWith('dashboard-demo-'))) } const prefersDark = savedTheme && savedTheme !== 'system' ? savedTheme === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches; setDark(prefersDark); document.documentElement.classList.toggle('dark', prefersDark); const syncTheme = () => setDark(document.documentElement.classList.contains('dark')); window.addEventListener('deci-theme-change', syncTheme); return () => window.removeEventListener('deci-theme-change', syncTheme) }, [demoStorageReady, mutateCache, savedTheme])
  const toggleTheme = () => { const next = !dark; setDark(next); document.documentElement.classList.toggle('dark', next); if (appConfig.dataMode === 'demo') demoRepositories.preferences.setTheme(next ? 'dark' : 'light'); else if (user) void saveUserTheme(next ? 'dark' : 'light').catch(() => window.alert('Your preference could not be saved.')) ; window.dispatchEvent(new Event('deci-theme-change')) }
  const active = pathname === '/' ? 'Home' : pathname.startsWith('/explore') || pathname.startsWith('/search') ? 'Explore' : pathname.startsWith('/topics') ? 'Topics' : pathname.startsWith('/activity') ? 'Activity' : pathname.startsWith('/articles/new') ? 'Create an article' : pathname.startsWith('/contributions') ? 'My contributions' : pathname.startsWith('/saved') ? 'Saved articles' : pathname.startsWith('/contributors') ? 'Contributors' : ''
  return <div className="app-frame"><AppSidebar active={active} mobileOpen={mobileOpen} onClose={() => setMobileOpen(false)}/><div className="app-main"><Topbar onMenu={() => setMobileOpen(true)} onTheme={toggleTheme} dark={dark}/><main className={`page-content ${pathname === '/' ? 'home-content' : ''}`}>{appConfig.dataMode === 'api' ? <section className="api-mode-notice" role="status"><span className="eyebrow">API MODE</span><h2>Backend adapter required</h2><p>API mode is selected, but this repository does not define the API schema or authentication contract yet. Demo fixtures are intentionally not shown as a fallback.</p></section> : !demoStorageReady ? <div className="page-loading" role="status">Restoring your local demo…</div> : children}<footer className="site-footer"><Link href="/" className="footer-brand">Decipedia</Link><span>Knowledge belongs to everyone.</span><span className="footer-mode"><span className="status-dot"/>{appConfig.dataMode === 'demo' ? 'Demo data · Not on-chain' : 'API mode · Adapter required'}</span></footer></main></div></div>
}
